// app/account/page.tsx — ported from pages/account.tsx (was getServerSideProps)
import Head from 'next/head';
import { getAccount } from '~/lib/data/account';
import { BillingButton } from './BillingButton';

export default async function AccountPage() {
  const account = await getAccount();
  return (
    <>
      <Head>
        <title>{account.name} — Account</title>
      </Head>
      <h1>{account.name}</h1>
      <p>Plan: {account.plan}</p>
      <BillingButton />
    </>
  );
}

// app/account/BillingButton.tsx
'use client';
import { useRouter } from 'next/router';

export function BillingButton() {
  const router = useRouter();
  return <button onClick={() => router.push('/account/billing')}>Billing</button>;
}
